export function pastPapersForTopic(topicId) {
  return PAST_PAPERS.entries.filter((e) => e.topics.includes(topicId));
}
export function pastPapersForUnit(subject, unitId) {
  return PAST_PAPERS.entries.filter(
    (e) => e.course === subject && e.topics.some((t) => t.startsWith(unitId + ':')),
  );
}
